var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var roots=scene.GetRootGameObjects();var map=GameObject.Find("MountainPassEnvironment");var objects=new System.Collections.Generic.List<object>();foreach(var tr in map.GetComponentsInChildren<Transform>(true)){var renderer=tr.GetComponent<Renderer>();var collider=tr.GetComponent<Collider>();if(renderer==null&&tr.parent!=map.transform)continue;objects.Add(new{name=tr.name,parent=tr.parent?.name,position=tr.position.ToString(),scale=tr.lossyScale.ToString(),mesh=tr.GetComponent<MeshFilter>()!=null?AssetDatabase.GetAssetPath(tr.GetComponent<MeshFilter>().sharedMesh):"",min=renderer!=null?renderer.bounds.min.ToString():"",max=renderer!=null?renderer.bounds.max.ToString():"",collider=collider!=null?collider.GetType().Name:"",material=renderer!=null?renderer.sharedMaterials.Select(AssetDatabase.GetAssetPath).ToArray():null});}var report=new{scene=scene.path,scene.isDirty,playing=EditorApplication.isPlaying,roots=roots.Select(r=>new{r.name,components=r.GetComponents<Component>().Select(c=>c!=null?c.GetType().Name:"missing").ToArray()}).ToArray(),objects};System.IO.File.WriteAllText("Assets/Temp/MountainPassPolish~/Test_SceneInspection.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return new{report.scene,report.isDirty,report.playing,rootNames=roots.Select(g=>g.name).ToArray(),inspected=objects.Count};
